package directroad

import (
	"context"
	"go/ast"
	"go/parser"
	"go/token"
	"io"
	"os"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/Agent-Field/codeaf/internal/livedoor"
)

// bogusSHA256Fingerprint is a syntactically valid SHA-256 SDP fingerprint line
// that will never match the ephemeral certificate generated by the host.
const bogusSHA256Fingerprint = "a=fingerprint:sha-256 00:11:22:33:44:55:66:77:88:99:AA:BB:CC:DD:EE:FF:00:11:22:33:44:55:66:77:88:99:AA:BB:CC:DD:EE:FF"

// Contract security: the DTLS fingerprint in the answer SDP is verified by
// pion during the DTLS handshake, and DisableCertificateFingerprintVerification
// is never referenced in non-test package source.
func TestTheDTLSFingerprintInTheAnswerIsVerified(t *testing.T) {
	// 1. Scan every non-test Go file in this directory to prove that
	// DisableCertificateFingerprintVerification is never called.
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatalf("os.ReadDir: %v", err)
	}
	fset := token.NewFileSet()
	scanned := 0
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		scanned++
		fileAST, err := parser.ParseFile(fset, name, nil, 0)
		if err != nil {
			t.Fatalf("parser.ParseFile(%s): %v", name, err)
		}
		ast.Inspect(fileAST, func(n ast.Node) bool {
			if ident, ok := n.(*ast.Ident); ok {
				if ident.Name == "DisableCertificateFingerprintVerification" ||
					ident.Name == "disableCertificateFingerprintVerification" {
					t.Fatalf("%s references forbidden identifier %s", name, ident.Name)
				}
			}
			return true
		})
	}
	if scanned == 0 {
		t.Fatal("expected to scan non-test Go source files, found 0")
	}

	// 2. The control: the same rig with nothing rewritten opens a stream, so the
	// failure below is the tampered fingerprint and not a broken rig.
	t.Run("an untampered answer opens a stream", func(t *testing.T) {
		rig := newVNetRig(t)
		host := New(rig.hostConfig())
		defer host.Close()
		hostCtx, hostCancel := context.WithCancel(context.Background())
		defer hostCancel()
		opened := make(chan struct{}, 1)
		host.SetAcceptor(hostCtx, func(ctx context.Context, stream io.ReadWriteCloser) {
			opened <- struct{}{}
			<-ctx.Done()
			_ = stream.Close()
		})
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		bridge := newSignalBridge(ctx, host, livedoor.Peer{Device: "device-control"})
		stream, err := Offer(ctx, rig.viewerConfig(), bridge.viewerSignaller(), bridge.deliver())
		if err != nil {
			t.Fatalf("the control Offer failed, so the tampered case proves nothing: %v", err)
		}
		defer func() { _ = stream.Close() }()
		select {
		case <-opened:
		case <-ctx.Done():
			t.Fatal("the control host never received its stream")
		}
	})

	// 3. Tamper with the answer SDP's a=fingerprint: line on the wire and verify
	// that Offer refuses to return a stream and the host keeps no open stream.
	rig := newVNetRig(t)

	hostCtx, hostCancel := context.WithCancel(context.Background())
	defer hostCancel()

	host := New(rig.hostConfig())
	defer host.Close()

	var hostStreamOpened atomic.Bool
	host.SetAcceptor(hostCtx, func(_ context.Context, stream io.ReadWriteCloser) {
		hostStreamOpened.Store(true)
		_ = stream.Close()
	})

	offerCtx, offerCancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer offerCancel()

	bridge := newSignalBridge(offerCtx, host, livedoor.Peer{Device: "device-fingerprint"})
	var tampered atomic.Bool
	bridge.hostHook = func(payload []byte) ([]byte, bool) {
		sig, err := livedoor.DecodeSignal(payload)
		if err != nil || sig.T != livedoor.SignalAnswer {
			return payload, true
		}
		lines := strings.Split(sig.SDP, "\n")
		for i, line := range lines {
			trimmed := strings.TrimRight(line, "\r")
			if strings.HasPrefix(trimmed, "a=fingerprint:") {
				lines[i] = bogusSHA256Fingerprint + "\r"
				tampered.Store(true)
			}
		}
		sig.SDP = strings.Join(lines, "\n")
		rewritten, err := livedoor.EncodeSignal(sig)
		if err != nil {
			t.Errorf("EncodeSignal tampered answer: %v", err)
			return payload, false
		}
		return rewritten, true
	}

	stream, err := Offer(offerCtx, rig.viewerConfig(), bridge.viewerSignaller(), bridge.deliver())
	if !tampered.Load() {
		t.Fatal("answer SDP contained no a=fingerprint: line to rewrite")
	}
	if err == nil {
		_ = stream.Close()
		t.Fatal("Offer succeeded despite a tampered DTLS fingerprint in the answer SDP")
	}
	t.Logf("the tampered Offer ended with: %v", err)
	if stream != nil {
		t.Fatalf("Offer returned non-nil stream on DTLS fingerprint failure: %v", stream)
	}

	eventually(t, 2*time.Second, "host to release pending session and hold no open streams", func() bool {
		return host.pendingCount() == 0 && host.streamCount() == 0
	})
	if hostStreamOpened.Load() && host.streamCount() != 0 {
		t.Fatal("host kept an open stream after DTLS fingerprint verification failed")
	}
}
